import { test, expect } from '@playwright/test';

test.describe('Dynamic Content Updates Announcement by Screen Readers', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dynamic-content');
  });

  test('should announce dynamic content updates using ARIA live regions', async ({ page }) => {
    // Verify initial content is visible
    const content = page.getByRole('region', { name: /dynamic content/i });
    await expect(content).toBeVisible();

    // Verify initial screen reader announcement
    await expect(page).toHaveScreenReaderRole('region');
    await expect(page).toHaveScreenReaderText('dynamic content');

    // Trigger content update
    const updateButton = page.getByRole('button', { name: /update content/i });
    await updateButton.click();

    // Wait for update to complete
    await page.waitForTimeout(500);

    // Verify updated content is announced
    await expect(page).toHaveScreenReaderText('updated dynamic content');

    // Verify previous content is no longer announced
    await expect(page).not.toHaveScreenReaderText('dynamic content');

    // Verify content is still visible
    await expect(content).toBeVisible();
  });

  test('should handle multiple content updates in quick succession', async ({ page }) => {
    // Verify initial content is visible
    const content = page.getByRole('region', { name: /dynamic content/i });
    await expect(content).toBeVisible();

    // Trigger first update
    const updateButton = page.getByRole('button', { name: /update content/i });
    await updateButton.click();

    // Wait for first update to complete
    await page.waitForTimeout(500);

    // Verify first update announcement
    await expect(page).toHaveScreenReaderText('updated dynamic content');

    // Trigger second update
    await updateButton.click();

    // Wait for second update to complete
    await page.waitForTimeout(500);

    // Verify second update announcement
    await expect(page).toHaveScreenReaderText('updated dynamic content');

    // Verify first update is no longer announced
    await expect(page).not.toHaveScreenReaderText('updated dynamic content');

    // Verify content is still visible
    await expect(content).toBeVisible();
  });
});
